@startuml

class Game {
  + id : string
}

class Player {
  + id : string
}

class Deck {
  + id : string
  + compareHeight(other: Card) : string
}

class Card {
  + id : string
  + suit : Suit
}

enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

class ScoringTable {
  + id : string
}

class Round {
  + id : string
  + pointValue : int
}

class JackRound extends Round {}

class SoloRound extends Round {}

class MandatorySoloRound extends MandatorySoloRound {}

class Solo {
  + type : SoloType
}

enum SoloType {
  TRUMP
  JACK
  QUEEN
}

Game "1" -- "4" Player
Game "1" -- "1" Deck
Game "1" -- "1" ScoringTable
ScoringTable "1" -- "*" Round
Round "1" -- "*" Player : winning players
SoloRound "1" -- "1" Solo : has
SoloRound "1" -- "1" Player : solo player

Deck "1" *-- "0..48" Card

@enduml

